<?php
require_once dirname(__DIR__,2).'/app/helpers.php';require_role('admin');require_once dirname(__DIR__,2).'/app/Services/ComplianceRiskService.php';$svc=new ComplianceRiskService(Database::connection());$db=Database::connection();$error=null;$success=null;if($_SERVER['REQUEST_METHOD']==='POST'){try{verify_csrf();if($_POST['action']==='kyc'){$svc->reviewKyc((int)$_POST['id'],(int)auth_user()['id'],$_POST['status'],$_POST['notes']??'');$success='KYC status updated.';}else{$svc->reviewAlert((int)$_POST['id'],(int)auth_user()['id'],$_POST['status'],$_POST['notes']??'');$success='Risk alert updated.';}}catch(Throwable $e){$error=$e->getMessage();}}
$kycs=$db->query('SELECT k.*,u.email FROM customer_kyc k JOIN users u ON u.id=k.user_id ORDER BY k.id DESC LIMIT 100')->fetchAll();$alerts=$svc->alerts('open',100);
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Compliance & Risk</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body><div class="container-fluid p-4"><div class="d-flex justify-content-between mb-4"><h2>Compliance & Risk</h2><a href="/commserve/public/admin/">Dashboard</a></div><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><?php if($success):?><div class="alert alert-success"><?=e($success)?></div><?php endif;?><h4>KYC Reviews</h4><div class="table-responsive mb-5"><table class="table table-sm align-middle"><thead><tr><th>Customer</th><th>Name</th><th>Document</th><th>Status</th><th>Review</th></tr></thead><tbody><?php foreach($kycs as $k):?><tr><td><?=e($k['email'])?></td><td><?=e($k['full_name'])?></td><td><?=e($k['document_type'])?> / <?=e($k['document_reference'])?></td><td><?=e($k['status'])?></td><td><form method="post" class="d-flex gap-2"><?=csrf_field()?><input type="hidden" name="action" value="kyc"><input type="hidden" name="id" value="<?=$k['id']?>"><input name="notes" class="form-control form-control-sm" placeholder="Notes"><button name="status" value="verified" class="btn btn-sm btn-success">Verify</button><button name="status" value="requires_review" class="btn btn-sm btn-warning">Review</button><button name="status" value="rejected" class="btn btn-sm btn-danger">Reject</button></form></td></tr><?php endforeach;?></tbody></table></div><h4>Open Risk Alerts</h4><div class="table-responsive"><table class="table table-sm align-middle"><thead><tr><th>Customer</th><th>Rule</th><th>Risk</th><th>Score</th><th>Reason</th><th>Action</th></tr></thead><tbody><?php foreach($alerts as $a):?><tr><td><?=e($a['email'])?></td><td><?=e($a['rule_code'])?></td><td><?=e($a['risk_level'])?></td><td><?=e((string)$a['score'])?></td><td><?=e($a['reason'])?></td><td><form method="post" class="d-flex gap-2"><?=csrf_field()?><input type="hidden" name="action" value="alert"><input type="hidden" name="id" value="<?=$a['id']?>"><input name="notes" class="form-control form-control-sm" placeholder="Notes"><button name="status" value="reviewing" class="btn btn-sm btn-warning">Review</button><button name="status" value="cleared" class="btn btn-sm btn-success">Clear</button><button name="status" value="blocked" class="btn btn-sm btn-danger">Block</button></form></td></tr><?php endforeach;?></tbody></table></div></div></body></html>
